content:
rule_id: R_G3_flat
description: Vehicles must not exceed the speed limit of the lane they are currently in. The plant’s speed measurement may have up to 1.0 m/s error, so the rule is expressed on the measured actual speed.
sampling_rate_hz: 10
horizon: 5
constants: {}
environment:
  signals:
    - {name: v_actual, sort: real}
    - {name: v_limit, sort: real}
formula: "G(v_actual <= v_limit)"
